\section{Introduction}

The CSS construction is described in at least three mutually translated
languages.  \emph{Classical coding}: two nested binary linear codes
$C_2 \subseteq C_1 \subseteq \FF_2^N$ give a quantum code with logical space
$C_1/C_2$.  \emph{Matrices}: two parity checks with $H_X H_Z^{\T} = 0$ give a
code with $k = N - \rank H_X - \rank H_Z$.  \emph{Stabilizers}: the $X$-type
operators indexed by the rows of $H_X$ and the $Z$-type ones indexed by the
rows of $H_Z$ generate an abelian Pauli subgroup whose joint $+1$ eigenspace is
the code space.  Everyone knows these agree; Section~\ref{sec:dict} makes
``agree'' exact, because statements are routinely asserted in one language and
tested in another.

A second slippage concerns geometry.  A commuting pair is a length-two chain
complex, and homology counts logical qubits.  But ``is a chain complex'' is far
weaker than ``is the incidence complex of a space''; Section~\ref{sec:graph}
measures the gap with a rank obstruction and two counterexamples.  The third
and most damaging slippage concerns distance: a homological code has two error
sectors and the distance is the smaller of the two, so quoting the systole
alone --- or, for a graph code, the girth --- can overstate the distance
arbitrarily.  Section~\ref{sec:dist} proves the $\min(\text{systole},
\text{cosystole})$ theorem and Section~\ref{sec:cube} applies it to the
hypercube, where folklore predicts distance $2^{n/2}$ and the truth is $1$.

\section{Setting and notation}

Fix a field $K$.  For $H \in K^{m\times N}$ write $Hv$ for the matrix--vector
product and $v\cdot w = \sum_i v_iw_i$ for the standard bilinear form on $K^N$.

\begin{definition}
The \emph{code checked by} $H$ is $\chk(H) = \ker H = \{v : Hv = 0\}$; the
\emph{row space} is $\rowsp(H) = \im H^{\T} = \{H^{\T}y : y \in K^m\}$.  For a
subspace $W \subseteq K^N$, $W^{\perp} = \{v : w\cdot v = 0 \ \forall w \in W\}$.
\end{definition}

\begin{definition}
For $a \in \FF_2^N$, the Hamming weight is $|a| = \#\{i : a_i \neq 0\}$.  For a
pair $p = (a\mid b)$, the Pauli weight is
$\|p\| = \#\{i : a_i \neq 0 \text{ or } b_i \neq 0\}$.
\end{definition}

Two facts used constantly: $|a|, |b| \le \|(a\mid b)\|$, and $\|p\| = 0$ iff
$p = 0$, so $\|p\| \ge 1$ for $p \neq 0$.

\section{The CSS dictionary}\label{sec:dict}

\begin{lemma}[Nondegeneracy]\label{lem:nondeg}
$(K^N)^{\perp} = 0$.
\end{lemma}

\begin{proof}[Proof sketch]
If $v\cdot w = 0$ for all $w$, let $w$ range over the standard basis.
\end{proof}

Nondegeneracy is the only property of the form used below; in particular we
never invoke $(W^{\perp})^{\perp} = W$.

\begin{theorem}[The checked code is an orthogonal complement]\label{thm:perp}
For every $H \in K^{m\times N}$ we have $\chk(H) = \rowsp(H)^{\perp}$.
\end{theorem}

\begin{proof}[Proof sketch]
Both inclusions follow from the adjunction $(H^{\T}y)\cdot v = y\cdot(Hv)$.  If
$Hv = 0$ the right-hand side vanishes for all $y$, so $v \perp \rowsp(H)$.
Conversely if $v \perp \rowsp(H)$ then $y \cdot (Hv) = 0$ for all $y$, and
Lemma~\ref{lem:nondeg} on $K^m$ gives $Hv = 0$.
\end{proof}

\begin{theorem}[Dictionary, part 1: nesting equals orthogonality]\label{thm:nest}
For $H_X \in K^{m_X\times N}$, $H_Z \in K^{m_Z\times N}$,
\[
  \rowsp(H_Z) \subseteq \chk(H_X)
  \iff
  H_X H_Z^{\T} = 0 .
\]
\end{theorem}

\begin{proof}[Proof sketch]
($\Leftarrow$) Every element of $\rowsp(H_Z)$ is $H_Z^{\T}y$ and
$H_XH_Z^{\T}y = 0$.  ($\Rightarrow$) Apply the inclusion to $H_Z^{\T}e_j$ for
each standard basis vector $e_j \in K^{m_Z}$: coordinatewise this says the
$j$-th column of $H_XH_Z^{\T}$ vanishes.
\end{proof}

Together with Theorem~\ref{thm:perp}, the informal condition
``$C_2 \subseteq C_1$'' with $C_1 = \chk(H_X)$, $C_2 = \rowsp(H_Z)$ is
\emph{literally} the orthogonality $\rowsp(H_X)\perp\rowsp(H_Z)$.

\begin{theorem}[$X \leftrightarrow Z$ symmetry]
$H_XH_Z^{\T} = 0 \iff H_ZH_X^{\T} = 0$.
\end{theorem}

\begin{proof}[Proof sketch]
Transpose, using $(AB)^{\T} = B^{\T}A^{\T}$.
\end{proof}

From here we work over $\FF_2$.

\begin{definition}[Symplectic form and stabilizer group]
A phase-free Pauli operator on $N$ qubits is a pair
$p = (a \mid b) \in \FF_2^N\times\FF_2^N$ ($X$-support $a$, $Z$-support $b$).
The commutation form is $\omega(p,q) = a_p\cdot b_q + a_q\cdot b_p$; $p$ and
$q$ commute iff $\omega(p,q) = 0$.  With
\[
  G(H_X,H_Z) = \{(h\mid 0) : h \text{ a row of } H_X\}
  \cup \{(0\mid h) : h \text{ a row of } H_Z\},
\]
the CSS stabilizer group is $\stab(H_X,H_Z) = \spn_{\FF_2} G(H_X,H_Z)$, written
additively.
\end{definition}

\begin{lemma}[Isotropy propagates from generators]\label{lem:iso}
If $\omega$ vanishes on all pairs from a set $G$, it vanishes on all pairs from
$\spn G$.
\end{lemma}

\begin{proof}[Proof sketch]
For fixed $g \in G$, $\{q : \omega(g,q) = 0\}$ is the kernel of a linear
functional, hence a subspace containing $G$ and therefore $\spn G$.  Now fix
$q \in \spn G$: by the previous step $\{p : \omega(p,q) = 0\}$ is the kernel of
a linear functional containing $G$, hence contains $\spn G$.  Only bilinearity
is used --- no basis and no finiteness of $G$.
\end{proof}

\begin{theorem}[Dictionary, part 3: abelian equals orthogonal]\label{thm:iso}
$\stab(H_X,H_Z)$ is isotropic if and only if $H_XH_Z^{\T} = 0$.
\end{theorem}

\begin{proof}[Proof sketch]
($\Leftarrow$) By Lemma~\ref{lem:iso} it suffices to check generators.  Two
$X$-type (resp.\ two $Z$-type) generators pair to $0$ trivially; an $X$-type
generator from row $i$ against a $Z$-type generator from row $j$ pairs to
$(H_X)_i\cdot(H_Z)_j = (H_XH_Z^{\T})_{ij} = 0$.  ($\Rightarrow$) Evaluating
$\omega$ on exactly that pair recovers the entry $(H_XH_Z^{\T})_{ij}$, which
must vanish for all $i,j$.
\end{proof}

\begin{corollary}[The dictionary]\label{cor:dict}
For binary parity checks $H_X, H_Z$ the following are equivalent:
(i) $\rowsp(H_Z)\subseteq\chk(H_X)$, i.e.\ $C_2 \subseteq C_1$;
(ii) $H_XH_Z^{\T} = 0$;
(iii) the stabilizer group $\stab(H_X,H_Z)$ is abelian.
\end{corollary}

\section{The chain complex and the dimension formula}

\begin{definition}
A \emph{CSS complex} over $K$ is $A \xrightarrow{d_2} B \xrightarrow{d_1} C$
with $d_1\circ d_2 = 0$.  Its cycles are $\ker d_1$, its boundaries
$\im d_2$, its homology $H = \ker d_1/\im d_2$, and $k = \dim H$ is the number
of logical qubits; $\beta_0 = \dim\coker d_1$.
\end{definition}

\begin{theorem}[Dictionary, part 2]\label{thm:complex}
If $H_XH_Z^{\T} = 0$ then
$K^{m_Z}\xrightarrow{H_Z^{\T}} K^{N}\xrightarrow{H_X} K^{m_X}$ is a CSS complex
with cycles $C_1 = \chk(H_X)$ and boundaries $C_2 = \rowsp(H_Z)$; conversely a
choice of bases turns any finite-dimensional CSS complex into such a pair.
\end{theorem}

\begin{corollary}
$k + \dim C_2 = \dim C_1$, so the logical space is canonically $C_1/C_2$.
\end{corollary}

\begin{theorem}[The CSS count]\label{thm:count}
Over a field, $k + \rank H_X + \rank H_Z = N$.
\end{theorem}

\begin{proof}[Proof sketch]
Rank--nullity gives $\dim C_1 = N - \rank H_X$, while
$\dim\rowsp(H_Z) = \rank H_Z^{\T} = \rank H_Z$ by equality of row and column
rank --- the only place the field hypothesis is genuinely needed, since the
equivalences of Section~\ref{sec:dict} hold over any commutative ring with a
nondegenerate dot product.
\end{proof}

\section{Distance}\label{sec:dist}

Throughout, $H_X,H_Z$ are binary and commuting, on $N$ physical qubits.

\begin{definition}
$a \in \FF_2^N$ is an \emph{$X$-logical} if $H_Za = 0$ and
$a \notin \rowsp(H_X)$; $b$ is a \emph{$Z$-logical} if $H_Xb = 0$ and
$b \notin \rowsp(H_Z)$.  The systole and cosystole are
\[
  d_X = \min\{|a| : a \text{ an } X\text{-logical}\},\qquad
  d_Z = \min\{|b| : b \text{ a } Z\text{-logical}\}.
\]
A Pauli operator $p = (a\mid b)$ is \emph{undetectable} if $H_Za = 0$ and
$H_Xb = 0$, and the \emph{CSS distance} is
\[
  d = \min\{\|p\| : p \text{ undetectable},\ p \notin \stab(H_X,H_Z)\}.
\]
\end{definition}

The definition of $d$ is operational and lets mixed $X/Z$ errors compete; the
theorem below is therefore not an unfolding of definitions.

\begin{theorem}[Structure of the stabilizer group]\label{thm:prod}
$\stab(H_X,H_Z) = \rowsp(H_X)\times\rowsp(H_Z)$.  Hence $(a\mid b)$ is a
stabilizer iff $a \in \rowsp(H_X)$ \emph{and} $b \in \rowsp(H_Z)$.
\end{theorem}

\begin{proof}[Proof sketch]
($\subseteq$) Every generator lies in the product, which is a subspace, hence
so does the span.  ($\supseteq$) Writing $H^{\T}y = \sum_i y_i H_i$ as a
combination of rows, $(a\mid 0)$ with $a = H_X^{\T}y$ is
$\sum_i y_i((H_X)_i \mid 0)$, and dually for $(0\mid b)$; add the two.
\end{proof}

\begin{lemma}[Padding]\label{lem:pad}
If both logical types exist then $d \le d_X$ and $d \le d_Z$.
\end{lemma}

\begin{proof}[Proof sketch]
If $a$ is a minimum-weight $X$-logical then $(a\mid 0)$ is undetectable, has
Pauli weight $|a| = d_X$, and is not a stabilizer, since by
Theorem~\ref{thm:prod} that would force $a \in \rowsp(H_X)$.
\end{proof}

\begin{theorem}[The distance theorem]\label{thm:dist}
If both an $X$-logical and a $Z$-logical exist, then $d = \min(d_X,d_Z)$.
\end{theorem}

\begin{proof}[Proof sketch]
``$\le$'' is Lemma~\ref{lem:pad}.  For ``$\ge$'': the competing set is
nonempty, so the minimum is attained by some undetectable non-stabilizer
$p = (a\mid b)$ with $\|p\| = d$.  By Theorem~\ref{thm:prod},
$a \notin \rowsp(H_X)$ or $b \notin \rowsp(H_Z)$.  In the first case $a$ is an
$X$-logical (undetectability gives $H_Za = 0$), so
$d_X \le |a| \le \|p\| = d$; in the second, symmetrically, $d_Z \le d$.
\end{proof}

The hypotheses are essential: when $k = 0$ there are no logical operators, the
minima are over empty sets, and the notion degenerates.

\begin{proposition}\label{prop:pos}
If some undetectable non-stabilizer error exists then $d \ge 1$.
\end{proposition}

\begin{proof}[Proof sketch]
A minimiser is nonzero, since the zero operator is a stabilizer, and
$\|p\| \ge 1$ for $p \neq 0$.
\end{proof}

\section{Which CSS complexes come from a graph?}\label{sec:graph}

\begin{definition}
$M \in \FF_2^{V\times E}$ \emph{is a graph incidence matrix} if for every
$e \in E$ there are $u \neq v$ in $V$ with $M_{we} = [w=u] + [w=v]$ for all
$w$.  Distinctness matters: loop columns are zero over $\FF_2$ and would
destroy the obstruction below.
\end{definition}

\begin{lemma}[Parity obstruction]\label{lem:parity}
Every column of a graph incidence matrix sums to zero, so $\bone \in \ker
M^{\T}$.
\end{lemma}

\begin{proof}[Proof sketch]
A column has exactly two ones and $1+1 = 0$ in $\FF_2$.
\end{proof}

\begin{theorem}[Graph rank obstruction]\label{thm:rankobs}
If $M \in \FF_2^{V\times E}$ is a graph incidence matrix and $V \neq
\emptyset$, then $\rank M + 1 \le |V|$.  In particular the $X$-checks of a
graph code are never independent.
\end{theorem}

\begin{proof}[Proof sketch]
$\bone \neq 0$ lies in $\ker M^{\T}$ by Lemma~\ref{lem:parity}, so
$\dim\ker M^{\T} \ge 1$; rank--nullity for $M^{\T}$ on $\FF_2^{V}$ and
$\rank M^{\T} = \rank M$ give the bound.
\end{proof}

\begin{theorem}[The Steane code is not a graph code]\label{thm:steanenotgraph}
The $3\times 7$ Hamming check matrix $H$ of Section~\ref{sec:steane} has
$\rank H = 3$, equal to its number of rows, so it is not a graph incidence
matrix on any vertex set.
\end{theorem}

\begin{theorem}[Minimal counterexample]
The $1\times 1$ matrix $[1]$ is a legitimate binary differential but is not a
graph incidence matrix: its single column would have to mark two distinct
vertices among one vertex.
\end{theorem}

\begin{proposition}
The hypercube boundary matrix of Section~\ref{sec:cube} \emph{is} a graph
incidence matrix and meets the bound of Theorem~\ref{thm:rankobs} with
equality, $\rank \partial_1 + 1 = 2^n$, because $Q_n$ is connected.
\end{proposition}

\begin{remark}
The obstruction is necessary, not sufficient: it says nothing about the
$Z$-side and only sees the parity shadow of the column weights.  A full
characterisation would demand every column of a $k$-dimensional simplicial
boundary map to have weight exactly $k+1$, plus face-compatibility relations.
\end{remark}

\section{The hypercube incidence complex}\label{sec:cube}

\begin{definition}
Let $V_n = \FF_2^n$ ($|V_n| = 2^n$) and let
$E_n = \{(i,x) : x_i = 0\}$ be the lower-endpoint normalised edge set, so each
geometric edge is named exactly once and $|E_n| = n2^{n-1}$.  The boundary
matrix $\partial_1 \in \FF_2^{V_n\times E_n}$ is
$(\partial_1)_{v,(i,x)} = [v = x] + [v = x + e_i]$.  Its transpose is the
discrete derivative, $(\partial_1^{\T}f)(i,x) = f(x) + f(x+e_i)$.
\end{definition}

\begin{theorem}[Cocycles are constants]\label{thm:cocyc}
$\ker \partial_1^{\T} = \FF_2\cdot\bone$.
\end{theorem}

\begin{proof}[Proof sketch]
($\supseteq$) The constant function gives $1+1 = 0$ on every edge.
($\subseteq$) The condition says $f(x) = f(x+e_i)$ whenever $x_i = 0$; applying
it at $x + e_i$ upgrades this to invariance under flipping any coordinate in
either direction.  Induct on the Hamming weight of $x$: if $x = 0$ we are
done, else pick $i$ with $x_i \neq 0$, note $x+e_i$ has smaller weight, and use
$f(x) = f(x+e_i) = f(0)$.
\end{proof}

\begin{theorem}[Rank of the cube boundary]\label{thm:cuberank}
$\rank \partial_1 + 1 = 2^n$, i.e.\ $\rank \partial_1 = 2^n - 1$.  Equivalently
$\beta_0 = 1$: the hypercube is connected.
\end{theorem}

\begin{proof}[Proof sketch]
By Theorem~\ref{thm:cocyc} the kernel of $\partial_1^{\T}$ is one-dimensional;
rank--nullity on $\FF_2^{V_n}$ and $\rank\partial_1^{\T} = \rank\partial_1$
give the claim.
\end{proof}

The homological code of a graph has $H_X = \partial_1$ (one $X$-check per
vertex) and $H_Z = 0$, since a graph has no $2$-cells; the qubits are the
edges, so $N = n2^{n-1}$.

\begin{theorem}[Logical qubit count]\label{thm:cubek}
$k + 2^n = n2^{n-1} + 1$, i.e.\ $k = 2^{n-1}(n-2)+1$ for $n \ge 1$.
\end{theorem}

\begin{proof}[Proof sketch]
Theorem~\ref{thm:count} with $\rank H_Z = 0$ gives $k = N - \rank \partial_1$;
substitute $N = n2^{n-1}$ and Theorem~\ref{thm:cuberank}.
\end{proof}

